import axios from 'axios'

// Football-Data.org API
const API_KEY = '5ac44b9e7ae64f30891be70bacd04900'
const BASE_URL = 'https://api.football-data.org/v4'

const apiClient = axios.create({
    baseURL: BASE_URL,
    headers: {
        'X-Auth-Token': API_KEY
    }
})

// Competition IDs
export const COMPETITIONS = {
    PREMIER_LEAGUE: 'PL',
    LA_LIGA: 'PD',
    BUNDESLIGA: 'BL1',
    SERIE_A: 'SA',
    LIGUE_1: 'FL1',
    CHAMPIONS_LEAGUE: 'CL',
    PSL: 'PSL', // May not be available in free tier
    AFCON: 'AFCON'
}

// Get matches (next 30 days)
export async function getTodaysMatches(competition = 'PL') {
    try {
        const today = new Date()
        const future = new Date()
        future.setDate(today.getDate() + 30)
        
        const response = await apiClient.get(`/competitions/${competition}/matches`, {
            params: {
                dateFrom: today.toISOString().split('T')[0],
                dateTo: future.toISOString().split('T')[0]
            }
        })
        return response.data.matches || []
    } catch (error) {
        console.error('Error fetching matches:', error)
        return []
    }
}

// Get matches by date range
export async function getMatchesByDateRange(startDate, endDate, competition = 'PL') {
    try {
        const response = await apiClient.get(`/competitions/${competition}/matches`, {
            params: {
                dateFrom: startDate,
                dateTo: endDate
            }
        })
        return response.data.matches || []
    } catch (error) {
        console.error('Error fetching matches by date:', error)
        return []
    }
}

// Get live matches
export async function getLiveMatches() {
    try {
        const today = new Date().toISOString().split('T')[0]
        const response = await apiClient.get(`/matches`, {
            params: {
                date: today,
                status: 'LIVE'
            }
        })
        return response.data.matches || []
    } catch (error) {
        console.error('Error fetching live matches:', error)
        return []
    }
}

// Get match by ID
export async function getMatchById(id) {
    try {
        const response = await apiClient.get(`/matches/${id}`)
        return response.data
    } catch (error) {
        console.error('Error fetching match:', error)
        return null
    }
}

// Get standings
export async function getStandings(competition = 'PL') {
    try {
        const response = await apiClient.get(`/competitions/${competition}/standings`)
        return response.data.standings || []
    } catch (error) {
        console.error('Error fetching standings:', error)
        return []
    }
}

// Get teams
export async function getTeams(competition = 'PL') {
