        return response.data.teams || []
    } catch (error) {
        console.error('Error fetching teams:', error)
        return []
    }
}

// Format match for display
export function formatMatch(match) {
    const homeTeam = match.homeTeam || {}
    const awayTeam = match.awayTeam || {}
    const competition = match.competition || {}
    
    // Determine match status
    let status = 'upcoming'
    const matchStatus = match.status || ''
    if (matchStatus === 'FINISHED') {
        status = 'finished'
    } else if (matchStatus === 'LIVE' || matchStatus === 'IN_PLAY') {
        status = 'live'
    }
    
    return {
        id: match.id,
        matchId: match.id,
        homeTeam: {
            name: homeTeam.name || 'Home',
            badge: getTeamEmoji(homeTeam.name)
        },
        awayTeam: {
            name: awayTeam.name || 'Away',
            badge: getTeamEmoji(awayTeam.name)
        },
        league: competition.name || 'Unknown League',
        leagueId: competition.code || 'unknown',
        kickoff: match.utcDate || new Date().toISOString(),
        status: status,
        score: {
            home: match.score?.fullTime?.home || match.score?.halfTime?.home || 0,
            away: match.score?.fullTime?.away || match.score?.halfTime?.away || 0
        },
        venue: match.venue || 'Unknown Venue',
        aiPrediction: generateAIPrediction(match)
    }
}

// Generate AI prediction based on match data
function generateAIPrediction(match) {
    // If match has scores, use them
    const homeScore = match.score?.fullTime?.home || match.score?.halfTime?.home || 0
    const awayScore = match.score?.fullTime?.away || match.score?.halfTime?.away || 0
    
    if (match.status === 'FINISHED') {
        return {
            result: {
                home: homeScore > awayScore ? 90 : 20,
